//! Layer A: deterministic inventories generated from upstream source.
//!
//! These files are regenerated byte-for-byte from an upstream revision, so a
//! migration run can update them mechanically and the diff is reviewable:
//!
//! * `compat/api/upstream-routes.json`: every `/api` route with action and
//!   middleware, from `routes/api.php` + the HTTP kernel aliases.
//! * `compat/baseline/supported-migrations.txt`: upstream migration names the
//!   Rust schema guard accepts.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::git::{Git, GitError};
use crate::php::routes::{ParseOptions, RouteDecl, parse_middleware_aliases, parse_routes};

pub const ROUTES_FILE: &str = "compat/api/upstream-routes.json";
pub const MIGRATIONS_FILE: &str = "compat/baseline/supported-migrations.txt";

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct RouteEntry {
    pub methods: Vec<String>,
    pub uri: String,
    pub action: String,
    pub middleware: Vec<String>,
}

impl From<RouteDecl> for RouteEntry {
    fn from(r: RouteDecl) -> Self {
        Self {
            methods: r.methods,
            uri: r.uri,
            action: r.action,
            middleware: r.middleware,
        }
    }
}

impl RouteEntry {
    pub fn key(&self) -> String {
        format!("{} {}", self.methods.join("|"), self.uri)
    }

    pub fn abilities(&self) -> Vec<String> {
        self.middleware
            .iter()
            .filter_map(|m| m.strip_prefix("App\\Http\\Middleware\\ApiAbility:"))
            .map(str::to_string)
            .collect()
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RouteInventory {
    pub generator: String,
    pub upstream_commit: String,
    pub routes: Vec<RouteEntry>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct RouteDiff {
    pub added: Vec<RouteEntry>,
    pub removed: Vec<RouteEntry>,
    /// (before, after) for routes whose action or middleware changed.
    pub changed: Vec<(RouteEntry, RouteEntry)>,
}

impl RouteDiff {
    pub fn is_empty(&self) -> bool {
        self.added.is_empty() && self.removed.is_empty() && self.changed.is_empty()
    }

    pub fn keys(&self) -> Vec<String> {
        self.added
            .iter()
            .chain(self.removed.iter())
            .map(RouteEntry::key)
            .chain(self.changed.iter().map(|(a, _)| a.key()))
            .collect()
    }
}

pub fn route_inventory(git: &Git, rev: &str) -> Result<RouteInventory, GitError> {
    let commit = git.rev_parse(rev)?;
    let routes_src = git.show(&commit, "routes/api.php")?.unwrap_or_default();
    let kernel_src = git
        .show(&commit, "app/Http/Kernel.php")?
        .unwrap_or_default();
    Ok(build_route_inventory(&commit, &routes_src, &kernel_src))
}

pub fn build_route_inventory(commit: &str, routes_src: &str, kernel_src: &str) -> RouteInventory {
    let opts = ParseOptions {
        base_prefix: "api".into(),
        base_middleware: vec!["api".into()],
        aliases: parse_middleware_aliases(kernel_src),
    };
    let mut routes: Vec<RouteEntry> = parse_routes(routes_src, &opts)
        .into_iter()
        .map(RouteEntry::from)
        .collect();
    routes.sort();
    RouteInventory {
        generator: format!("coolify-port {}", env!("CARGO_PKG_VERSION")),
        upstream_commit: commit.to_string(),
        routes,
    }
}

pub fn diff_routes(before: &[RouteEntry], after: &[RouteEntry]) -> RouteDiff {
    let b: BTreeMap<String, &RouteEntry> = before.iter().map(|r| (r.key(), r)).collect();
    let a: BTreeMap<String, &RouteEntry> = after.iter().map(|r| (r.key(), r)).collect();
    let mut diff = RouteDiff::default();
    for (k, r) in &a {
        match b.get(k) {
            None => diff.added.push((*r).clone()),
            Some(old) if old != r => diff.changed.push(((*old).clone(), (*r).clone())),
            Some(_) => {}
        }
    }
    for (k, r) in &b {
        if !a.contains_key(k) {
            diff.removed.push((*r).clone());
        }
    }
    diff
}

pub fn migration_names(git: &Git, rev: &str) -> Result<Vec<String>, GitError> {
    let mut names: Vec<String> = git
        .ls_tree(rev, "database/migrations")?
        .into_iter()
        .filter_map(|p| {
            p.strip_prefix("database/migrations/")
                .and_then(|f| f.strip_suffix(".php"))
                .map(str::to_string)
        })
        .collect();
    names.sort();
    Ok(names)
}

pub fn render_migrations_file(commit: &str, names: &[String]) -> String {
    let mut s = format!(
        "# Upstream migrations accepted by the coolify-rs schema guard.\n\
         # Generated by coolify-port from upstream {commit}. Do not edit by hand.\n"
    );
    for n in names {
        s.push_str(n);
        s.push('\n');
    }
    s
}

pub fn render_routes_file(inv: &RouteInventory) -> String {
    // Pretty JSON with a trailing newline keeps diffs line-oriented.
    let mut s = serde_json::to_string_pretty(inv).unwrap_or_default();
    s.push('\n');
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn r(m: &str, uri: &str, mw: &[&str]) -> RouteEntry {
        RouteEntry {
            methods: vec![m.into()],
            uri: uri.into(),
            action: "A@b".into(),
            middleware: mw.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn diffs_routes() {
        let before = vec![
            r("GET", "api/v1/a", &["read"]),
            r("GET", "api/v1/b", &["read"]),
        ];
        let after = vec![r("GET", "api/v1/a", &["write"]), r("POST", "api/v1/c", &[])];
        let d = diff_routes(&before, &after);
        assert_eq!(d.added.len(), 1);
        assert_eq!(d.removed[0].uri, "api/v1/b");
        assert_eq!(d.changed[0].1.middleware, vec!["write"]);
        assert_eq!(d.keys().len(), 3);
    }
}
